void validateDbProperties(Properties p) {
  List<String> missing = new ArrayList<>();
  for (String key : List.of("db.url", "db.username", "db.driver")) {
    if (p.getProperty(key, "").isEmpty()) missing.add(key);
  }
  if (!missing.isEmpty()) throw new IllegalStateException("brakujace klucze: " + missing);
}

