String resolveDbUrl(Properties p) {
  String fromSystem = System.getProperty("db.url");
  if (fromSystem != null) return fromSystem;
  String fromEnv = System.getenv("DB_URL");
  if (fromEnv != null) return fromEnv;
  String fromFile = p.getProperty("db.url");
  if (fromFile != null) return fromFile;
  return "jdbc:h2:mem:default";
}

